CREATE FUNCTION population_top3000_202608_202609_v1.s01_reviewed_correction_binding_v1(p_company text,p_date date,p_source_snapshot_sha text,p_source_key jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='pg_catalog' AS $fn$
DECLARE producer jsonb;review jsonb;pin jsonb;point jsonb;snapshot jsonb;n bigint;quality population_top3000_202608_202609_v1.pipeline_quality_evidence%ROWTYPE;
BEGIN
IF jsonb_typeof(p_source_key) IS DISTINCT FROM 'object' OR p_source_key->>'release_id' IS NULL OR p_source_key->>'partition_key' IS NULL OR p_source_key->>'unit_key' IS NULL OR p_company IS NULL OR p_date IS NULL OR p_source_snapshot_sha IS NULL OR p_source_snapshot_sha !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'S01_BINDING_INPUT_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a JOIN population_top3000_202608_202609_v1.pipeline_control c ON c.singleton=a.singleton WHERE a.singleton AND a.owner_id='top3000-completion-20261024-root-5db48b32d103' AND a.owner_fence=3 AND a.stop_generation=1 AND a.enabled IS TRUE AND a.stopped IS FALSE AND a.hold_reason IS NULL AND a.admitted_until>clock_timestamp() AND c.enabled IS TRUE AND c.deadline>clock_timestamp() AND c.expected_owner_id=a.owner_id AND c.expected_owner_fence=a.owner_fence AND c.expected_stop_generation=a.stop_generation AND a.scope_sha256='8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' AND c.scope_sha256=a.scope_sha256) THEN RAISE EXCEPTION 'S01_BINDING_CONTROL_HOLD';END IF;
SELECT details INTO STRICT producer FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=104400;
SELECT details INTO STRICT review FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=116018;
IF encode(sha256(convert_to(producer::text,'UTF8')),'hex') IS DISTINCT FROM 'ac3aa9c3f413d5a38217834b2be3ee588f1d3f50d8f539413a2fb1293500d78c'
OR encode(sha256(convert_to(review::text,'UTF8')),'hex') IS DISTINCT FROM 'a412524c638b56121b52040184abf54950e57dc87260b2faa663686c8be75a07' THEN RAISE EXCEPTION 'S01_BINDING_EVIDENCE_PIN_CHANGED';END IF;
SELECT * INTO STRICT quality FROM population_top3000_202608_202609_v1.pipeline_quality_evidence WHERE evidence_id='e3943ee0-d0c6-4354-848d-ef0839918f00';
IF quality.family_id IS DISTINCT FROM 'S01' OR quality.result IS DISTINCT FROM 'PASS' OR quality.independent_of_producer IS DISTINCT FROM true OR quality.discrepancy_count IS DISTINCT FROM 0 OR quality.check_version IS DISTINCT FROM 's01-correction-review-20261027-0915' OR quality.input_versions->>'producer_sha256' IS DISTINCT FROM 'ac3aa9c3f413d5a38217834b2be3ee588f1d3f50d8f539413a2fb1293500d78c' OR quality.input_versions->>'review_sha256' IS DISTINCT FROM 'a412524c638b56121b52040184abf54950e57dc87260b2faa663686c8be75a07' THEN RAISE EXCEPTION 'S01_BINDING_QUALITY_PIN_CHANGED';END IF;
IF encode(sha256(convert_to(pg_get_viewdef('population_top3000_202608_202609_v1.working_d02_adig_corroborated_points_v1'::regclass,true),'UTF8')),'hex') IS DISTINCT FROM '7a961ed519344992a07b862475c17e006cdcc2057bc5fc8a5c4694d76098d151'
OR encode(sha256(convert_to(pg_get_viewdef('population_top3000_202608_202609_v1.working_d02_sec_corroborated_points_v1'::regclass,true),'UTF8')),'hex') IS DISTINCT FROM 'c8ad22281ba795ae1431f93d7bb2c829a43f01719ed8c7edb51181317b237af6' THEN RAISE EXCEPTION 'S01_BINDING_VIEW_PIN_CHANGED';END IF;
SELECT count(*),jsonb_agg(value)->0 INTO n,pin FROM jsonb_array_elements(producer->'correction_rows') WHERE value->>'company_id'=p_company AND (value->>'session_date')::date=p_date;
IF n<>1 OR pin->>'overlay_state' IS DISTINCT FROM 'CORRECTED_DATED_POINT_SOURCE_LINK_ONLY' OR jsonb_array_length(pin->'records') IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S01_BINDING_UNREVIEWED_POINT';END IF;
WITH points AS(SELECT to_jsonb(v) j FROM population_top3000_202608_202609_v1.working_d02_adig_corroborated_points_v1 v WHERE company_id=p_company AND session_date=p_date UNION ALL SELECT to_jsonb(v) FROM population_top3000_202608_202609_v1.working_d02_sec_corroborated_points_v1 v WHERE company_id=p_company AND session_date=p_date)
SELECT count(*),jsonb_agg(j)->0 INTO n,point FROM points;
IF n<>1 OR point->'dated_point_and_source_link_verified' IS DISTINCT FROM 'true'::jsonb OR EXISTS(SELECT 1 FROM unnest(ARRAY['company_id','company_ordinal','session_date','ticker','identity_source_id','identity_source_ordinal','identity_record_sha256','qualification_event_id']) k WHERE point->k IS DISTINCT FROM pin->k) THEN RAISE EXCEPTION 'S01_BINDING_IDENTITY_CHANGED';END IF;
SELECT count(*),jsonb_agg(to_jsonb(o))->0 INTO n,snapshot FROM population_top3000_202608_202609_v1.source_observation o WHERE o.release_id=p_source_key->>'release_id' AND o.partition_key=p_source_key->>'partition_key' AND o.unit_key=p_source_key->>'unit_key' AND o.family_id='S01' AND o.source_id=pin#>>'{records,0,source_id}' AND o.source_record_key=pin#>>'{records,0,source_record_key}';
IF n<>1 OR snapshot->>'record_sha256' IS DISTINCT FROM pin#>>'{records,0,record_sha256}' OR snapshot->>'normalization_sha256' IS DISTINCT FROM pin#>>'{records,0,normalization_sha256}' OR snapshot->>'effective_date' IS DISTINCT FROM p_date::text OR snapshot#>>'{values_json,symbol}' IS DISTINCT FROM pin->>'ticker' OR encode(sha256(convert_to(snapshot::text,'UTF8')),'hex') IS DISTINCT FROM p_source_snapshot_sha THEN RAISE EXCEPTION 'S01_BINDING_SOURCE_CHANGED';END IF;
RETURN jsonb_build_object('version','S01_REVIEWED_POINT_BINDING_V1','source_snapshot',snapshot,'source_snapshot_sha256',p_source_snapshot_sha,'binding',pin-'records','producer_event_id',104400,'review_event_id',116018,'quality_evidence_id',quality.evidence_id,'source_company_id_preserved',true,'original_temporal_fields_preserved',true,'historical_predictor_eligible',false,'family_accepted',false,'qualification','DATED_POINT_SOURCE_LINK_ONLY');
END $fn$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.s01_reviewed_correction_binding_v1(text,date,text,jsonb) FROM PUBLIC,anon,authenticated;

